import { Routes } from '@angular/router';
import { DashboardComponent } from './dashboard/dashboard.component';
import { FoliosSesionesComponent } from './folios-sesiones/folios-sesiones.component';

import { UsuariosComponent } from './usuarios/usuarios.component';
import { DocumentosComponent } from "./documentos/documentos.component";
import { EstadoCuentaComponent } from './estado-cuenta/estado-cuenta.component';
import { CotizadorComponent } from './cotizador/cotizador.component';
import { DigitalizadosComponent } from './digitalizados/digitalizados.component';

export const mainRoutes: Routes = [
    { path: '', redirectTo: 'dashboard', pathMatch: 'full' },
    { path: 'dashboard', component: DashboardComponent },
    {
        title: 'Cotizador',
        path: 'cotizador',
        component: CotizadorComponent,
    },
    {
        path: 'usuarios',
        title: 'usuarios',
        component: UsuariosComponent,
        loadChildren: () => import('./usuarios/usuarios.routes').then(m => m.usuariosRoutes),
    },
    {
        path: 'apoyos',
        title: 'apoyos',
        loadChildren: () => import('./apoyos/apoyos.routes').then(m => m.apoyosRoutes),
    },
    {
        path: 'creditos',
        title: 'creditos',
        loadComponent: () => import('./creditos/creditos.component').then(c => c.CreditosComponent),
        loadChildren: () => import('./creditos/creditos.routes').then(m => m.creditosRoutes),
    },
    {
        path: 'estado-cuenta',
        title: 'Estado de Cuentas',
        component: EstadoCuentaComponent,
        loadChildren: () => import('./estado-cuenta/estado.cuentas.routes').then(m => m.estadoCuentasRoutes)
    },
    { path: 'folios-sesiones', component: FoliosSesionesComponent },
    { path: 'docs-tests', component: DocumentosComponent },
    {
        title: 'Juridico',
        path: 'juridico',
        loadChildren: () => import('./juridico/juridico.routes').then(m => m.juridicoRoutes),
    },
    {
        title: 'Cobranza',
        path: 'cobranza',
        loadChildren: () => import('./cobranza/cobranza.routes').then(m => m.cobranzaRoutes),
    },
    {
        title: 'Convenios',
        path: 'convenios',
        loadChildren: () => import('./convenios/convenios.routes').then(m => m.conveniosRoutes),
    },
    {
        title: 'Reportes',
        path: 'reportes',
        loadChildren: () => import('./reportes/reportes.routes').then(m => m.reportesRoutes),
    },
    {
        path: 'informes',
        title: 'Informes',
        loadComponent: () => import('./informes/informes.component').then(m => m.InformesComponent),
        loadChildren: () => import('./informes/informes.routes').then(m => m.informesRoutes)
    },
    {
        path: 'digitalizados',
        component: DigitalizadosComponent,
    },
    {
        path: 'digitalizados/:credito_id',
        component: DigitalizadosComponent,
    },
];
