import { Injectable } from '@angular/core';

//-------[Setting up Pdfmake]--------|
import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
(<any>pdfMake).addVirtualFileSystem(pdfFonts);

import { UtilsService } from '../../utils.service';
import { UtilsService as UtilsContratos } from '../utils.service';
import { CreditoService } from '../../../controllers/credito.service';
import { Credito } from '../../../models/credito.model';
import { UtilsEstadoCuentaService } from '../../../main/estado-cuenta/services/utils-estado-cuenta.service';
import { ChronixPDFservice } from '../ChronixPDF.service';

//--------[Injecting the necessary dependencies]--------|
@Injectable({
  providedIn: 'any',
})

export class solicitudReestructura {

  constructor(
    private utils: UtilsService,
    private utilsC: UtilsContratos,
    private creditoController: CreditoService,
    private utilsEstadoCuenta: UtilsEstadoCuentaService,
    private chronixPDF: ChronixPDFservice
  ) { }

 async generarSolicitudReestructura(creditoParam: number | Credito | undefined) {
    let creditoID = this.utilsC.validarCreditoID(creditoParam);

    // Importing the necessary relations from the database to the variable
    const credito = await this.creditoController.find(creditoID, [
      'datosPersonasMorales',
      "datosPersonasMorales.ciudades",
      "datosPersonasMorales.representanteLegal",
      "datosPersonasMorales.representanteLegal.telefonosPersonales",
      "datosPersonasMorales.representanteLegal.ciudades",

      "datosPersonaFisica",
      "datosPersonaFisica.datosPersonales",
      "datosPersonaFisica.datosPersonales.telefonosPersonales",
      "datosPersonaFisica.negocios",

      "estadoCuenta",
      "abonos",
      "creditosPagos",

      "productosFinancieros",
      "sucursales",
      "sesiones"
    ])

      if(!credito) return;

  const creditoOriginal = await this.creditoController.creditoOriginalFromReestructuradoS2c(credito)
  if(creditoOriginal){
    credito.datos_persona_fisica = creditoOriginal.datos_persona_fisica
    credito.datos_personas_morales = creditoOriginal.datos_personas_morales
  }

    const tablaDPF = credito.datos_persona_fisica;
    const tablaDP = credito.datos_persona_fisica?.datos_personales;
    const tablaDPM = credito.datos_personas_morales;
    const tablaRL = credito.datos_personas_morales?.representante_legal;
    const tablaEstadoCuenta = this.utilsEstadoCuenta.getEstadoCuenta(credito);
    const tablaEstadoCuentaCliente = this.utilsEstadoCuenta.getEstadoCuentaCliente(credito);

    const telefonosCasaPM = this.utilsC.getTelefonosCasa(tablaRL?.telefonos_personales ?? [])
    const telefonosOficinaPM = this.utilsC.getTelefonosOficina(tablaRL?.telefonos_personales ?? [])
    const telefonosCelularPM = this.utilsC.getTelefonosCelular(tablaRL?.telefonos_personales ?? [])

    const telefonosCasaPF = this.utilsC.getTelefonosCasa(tablaDP?.telefonos_personales ?? [])
    const telefonosOficinaPF = this.utilsC.getTelefonosOficina(tablaDP?.telefonos_personales ?? [])
    const telefonosCelularPF = this.utilsC.getTelefonosCelular(tablaDP?.telefonos_personales ?? [])

    const telefonoPM = this.utilsC.combineTelefonosSacaUnNumero(telefonosCasaPM, telefonosCelularPM, telefonosOficinaPM)
    const telefonoPF = this.utilsC.combineTelefonosSacaUnNumero(telefonosCasaPF, telefonosCelularPF, telefonosOficinaPF)

    const fechaInicioReestructura = this.utilsC.fechaAletras(tablaEstadoCuentaCliente?.fechaUltimoPago),
          nombreAcreditadoRazonSocial = this.utils.nombreClienteFromCredito(credito),
          folio = credito.folio?.toUpperCase(),
          email = tablaDP?.email ?? tablaRL?.email,
          telefono = telefonoPM !== 'N/A' ? telefonoPM : telefonoPF,
          nombrePrograma = credito.productos_financieros?.alias.toUpperCase(),
          interesMoratorioAcumulado = tablaEstadoCuenta?.interes_moratorio,
          saldoVencido = tablaEstadoCuenta?.saldo_vencido,
          montoMinistrar = credito.monto_autorizado, // Cual es este? XD
          montoTotalPagado = tablaEstadoCuenta?.monto_total_pagado,
          fechaApertura = this.utilsC.fechaAletras(tablaEstadoCuenta?.fecha_inicio), // Es esto? o tablaEstadoCUentaCliente?.fechaApertura?
          fechaFinal = fechaInicioReestructura,
          fechaUltimoPago = this.utilsC.fechaAletras(tablaEstadoCuentaCliente?.fechaUltimoPago),
          referenciaBancaria = credito.referencia_bancaria.toUpperCase()

    const headerLogo = await this.chronixPDF.generateHeader(
      ['assets/logo_baja_california.png', 'assets/carta_instruccion1.png', 'assets/fondosBCrecortado.png'],
      [130, 130, 130],
      [150, 130, 120]
    )
    const backgroundLogo = await this.utilsC.backgroundLogo('assets/logoMexico.png');

    const generatedDocument: any = {
      pageMargins: [60, 20, 60, 40],
      content: [
        {...headerLogo},

        {
          text: [
            'Fecha: ',
            { text: fechaInicioReestructura, bold: true }
          ],
          alignment: 'right',
          fontSize: 10,
          margin: [0, 20, 0, 10]
        },

        { text: 'Formato de Solicitud de Reestructura de Crédito', bold: true, alignment: 'center', fontSize: 15, margin: [0, 20, 0, 30] },

        {
          layout: 'noBorders',
          table: {
            widths: [100, '*', 100, '*'],
            body: [
              [
                { text:  "Nombre completo:", alignment: 'left' },
                { text: nombreAcreditadoRazonSocial, bold: true },
                { text: 'ID Crédito:', margin: [25, 0, 0, 0] },
                { text: folio, bold: true }
              ],
              [
                { text: '\nCorreo electrónico:' },
                { text: '\n' + email, bold: true },
                { text: '\nTeléfono', margin: [25, 0, 0, 0] },
                { text: '\n' + telefono, bold: true },
              ]
            ]
          },
          fontSize: 10
        },

        {
          text: [
            '\nReconozco la deuda con el Fideicomiso para el Desarrollo Económico de Baja California del programa ',
            { text: nombrePrograma, bold: true },
            ', así mismo solicito la condonación de intereses moratorios los cuales ascienden al monto de ',
            { text: '$ ' + this.utilsC.formatearNumeroConComas(interesMoratorioAcumulado), bold: true },
            ' generado por un saldo vencido de ',
            { text: '$ ' + this.utilsC.formatearNumeroConComas(saldoVencido), bold: true },
            '\n'
          ],
          alignment: 'justify',
          fontSize:10
        },

        { text: 'Estado de cuenta', bold: true, alignment: 'center', fontSize: 14, margin: [0, 20, 0, 20] },

        {
          layout: 'noBorders',
          table: {
            widths: [110, '*', 110, '*'],
            body: [
              [
                { text:  "Monto total del crédito:", alignment: 'left' },
                { text: '$ ' + this.utilsC.formatearNumeroConComas(montoMinistrar!), bold: true, alignment: 'right' },
                { text: 'Fecha de inicio:', margin: [25, 0, 0, 0] },
                { text: fechaApertura, bold: true }
              ],
              [
                { text: '\nMonto total pagado:' },
                { text: '\n$ ' + this.utilsC.formatearNumeroConComas(montoTotalPagado), bold: true, alignment: 'right' },
                { text: '\nFecha de final', margin: [25, 0, 0, 0] },
                { text: '\n' + fechaFinal, bold: true }
              ],
              [
                { text: '\nMonto total de adeudo:' },
                { text: '\n$ ' + this.utilsC.formatearNumeroConComas(saldoVencido), bold: true, alignment: 'right' },
                { text: '\nFecha de último pago', margin: [25, 0, 0, 0] },
                { text: '\n' + fechaUltimoPago, bold: true }
              ]
            ]
          },
          fontSize: 9
        },

        { text: 'Justificación de atraso en sus mensualidades', alignment: 'left', fontSize: 12, margin: [0, 20, 0, 15] },

        {
          canvas: [
            {
              type: 'rect',
              x: 0,
              y: 0,
              w: 475,
              h: 120,
              absolutePosition: { x: 210, y: 400 } // Dynamically centers it (A4 width ~ 595)
            }
          ]
        },

        { text: 'Propuesta de esquema de pagos', alignment: 'left', fontSize: 12, margin: [0, 15, 0, 15] },

        {
          canvas: [
            {
              type: 'rect',
              x: 0,
              y: 0,
              w: 475,
              h: 120,
              absolutePosition: { x: 210, y: 400 } // Dynamically centers it (A4 width ~ 595)
            }
          ],
          margin: [0, 0, 0, 30]
        },

        {
          text: [
            '\n\nCantidades que deberían ser depositadas a más tardar, el día convenido de pago en el banco HSBC MÉXICO, SOCIEDAD ANONIMA INSTITUCION DE BANCA MULTIPLE, GRUPO FINANCIERO HSBC, a la cuenta de nombre FIDEICOMISO PARA EL DESARROLLO ECONÓMICO DE BAJA CALIFORNIA HBMX53260, CLAVE DE SERVICIO 8727, CUENTA 6231216641, CLABE INTERBANCARIA 021028062312166411, con referencia bancaria ',
            { text: referenciaBancaria, bold: true }
          ],
          alignment: 'justify',
          fontSize: 10,
          pageBreak: 'before',
          margin: [0, 30, 0, 0]
        },

        {
          text: '\nLo anterior queda condicionado a que sea exigido por el fideicomitente o la fiduciaria: el pago total del adeudo reconocido y para el caso de vuelva a incurrir en mora, me comprometo a cubrir el total de los intereses moratorios que me descontaron, así como los que se generen con posterioridad y las mensualidades subsecuentes.',
          alignment: 'justify',
          fontSize: 10
        },

        { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 200, y2: 0, lineWidth: 1, lineColor: '#000000' }], margin: [0, 80, 0, 10], alignment: "center" },
        { text: nombreAcreditadoRazonSocial, bold: true, alignment: 'center' },
        { text: 'Nombre y firma del acreditado/razón social', alignment: 'center', margin: [0, 10, 0, 0], fontSize: 10 },
      ],
    }
    pdfMake.createPdf(generatedDocument).open();
  }
}
