import { Component, effect, input } from '@angular/core';
import { CreditoContratoDocumento } from '../../../models/credito.contrato.documento';
import { CreditoContratoDocumentoService } from '../../../controllers/credito.contrato.documento.service';
import { UtilsService } from '../../../services/utils.service';

@Component({
  selector: 'app-contratos',
  imports: [],
  templateUrl: './contratos.component.html',
  styleUrl: './contratos.component.css'
})
export class ContratosComponent {
  creditoId = input<number | undefined>();
  documentos: CreditoContratoDocumento[] = [];

  constructor(
    private contratosService: CreditoContratoDocumentoService,
    public utils: UtilsService,
  ) {
    effect(async () => {
      const id = this.creditoId();
      this.documentos=[]
      if (id) {
        this.documentos = await this.contratosService.all({
          conditionals: [
            {
              key:'credito_id',
              operator:'=',
              value:id,
            },
            {
              key:'documento_url',
              operator:'IS NOT NULL',
              value:'null',
            }
          ],
          loader:false,
        });
      }
    });
  }
}