import { Component, input, effect, Input } from '@angular/core';
import { DocumentoS2cService } from '../../../controllers/documento.s2c.service';
import { DocumentoS2c } from '../../../models/credito.model';
import { UtilsService } from '../../../services/utils.service';

@Component({
  selector: 'app-documentos-s2c',
  imports: [

  ],
  templateUrl: './documentos-s2c.component.html',
  styleUrl: './documentos-s2c.component.css'
})
export class DocumentosS2cComponent {
  @Input() title ='Documentos Migrados S2c'
  creditoId = input<number | undefined>();
  documentos: DocumentoS2c[] = [];
  @Input() tipo:'CONTRATO'|'SOLICITUD'='CONTRATO'


  constructor(
    private documentoS2cController: DocumentoS2cService,
    public utils: UtilsService,
  ) {
    effect(async () => {
      const id = this.creditoId();
      this.documentos=[]
      if (id) {
        this.documentos = await this.documentoS2cController.all({
          conditionals: { 
            credito_id: id, 
            tipo: this.tipo,
          },
          loader:false,
        });
      }
    });
  }
}