import { Component } from '@angular/core';
import { BuscadorCreditosComponent } from "../estado-cuenta/shared/buscador-creditos/buscador-creditos.component";
import { DocumentosS2cComponent } from "./documentos-s2c/documentos-s2c.component";
import { ContratosComponent } from "./contratos/contratos.component";
import { ActivatedRoute, Router } from '@angular/router';
import { DocumentosComponent } from './documentos/documentos.component';
import { Credito } from '../../models/credito.model';
import { CreditoService } from '../../controllers/credito.service';

@Component({
  selector: 'app-digitalizados',
  imports: [BuscadorCreditosComponent, DocumentosS2cComponent, ContratosComponent, DocumentosComponent],
  templateUrl: './digitalizados.component.html',
  styleUrl: './digitalizados.component.css'
})
export class DigitalizadosComponent {
  creditoId ?: number;
  credito ?: Credito;

  constructor(
    private router:Router,
    private route: ActivatedRoute,
    private creditoService: CreditoService
  ){}

  ngOnInit(){
    this.route.params.subscribe(params => {
      const id= params['credito_id']
      if(id){        
        this.setCreditoById(id)        
      }
    })
  }

  private async setCreditoById(id: number){
    this.credito = await this.creditoService.find(id,[
      'documentos',
      'usuarios',
      'productosFinancieros.documentos.documento',
      'documentos.productosFinancierosDocumentos.documento',
    ])
    this.creditoId= +id    
  }

  updateUrl(){
    this.router.navigate(['/main/digitalizados/',this.creditoId])
  }
}
