import { Component } from '@angular/core';
import { TablaComponent } from "../../shared/tabla/tabla.component";
import { FormularioFlotanteComponent } from "../../shared/formulario-flotante/formulario-flotante.component";
import { Form, GenericFormComponent } from "../../shared/generic-form/generic-form.component";


const FORM:Form=[
  {
    label:'Sesión',
    type:'text',
    value:'',
    key:'sesion',
    style:{
      div:'p-3 col-12 col-sm'
    },
    validator:{
      required:true
    }
  },
  {
    label:'Fecha sesión',
    key:'fecha_sesion',
    value:'',
    type:'date',
    style:{
      div:'p-3 col-12 col-sm'
    },
    validator:{
      required:true
    }
  }
]

@Component({
    selector: 'app-folios-sesiones',
    imports: [
    TablaComponent,
    FormularioFlotanteComponent,
    GenericFormComponent
],
    templateUrl: './folios-sesiones.component.html',
    styleUrl: './folios-sesiones.component.css'
})
export class FoliosSesionesComponent {
  showAdd:boolean=false
  title:string='Nuevo folio de sesión'
  form:Form=this.copyOf(FORM)

  onClose(){
    if(!this.showAdd){
      this.form=this.copyOf(FORM)
    }
  }
  copyOf(value:any){
    return JSON.parse(JSON.stringify(value))
  }
}
