import { Component, effect, input } from '@angular/core';
import { UtilsService } from '../../../services/utils.service';
import { CreditoProductoFinancieroDocumento } from '../../../models/creditos.productos.financieros.documento';
import { Credito } from '../../../models/credito.model';

@Component({
  selector: 'app-documentos',
  standalone: true,
  imports: [

  ],
  templateUrl: './documentos.component.html',
  styleUrl: './documentos.component.css'
})
export class DocumentosComponent {  
  credito = input<Credito>();
  documentos: CreditoProductoFinancieroDocumento[] = [];

  constructor(    
    public utils: UtilsService,
  ) {
    effect(() => {                 
      const currentCredito = this.credito();
      if (currentCredito?.documentos) {                
          this.documentos = currentCredito.documentos;  
          console.log(this.documentos);                       
      }
      else{
        this.documentos = [];        
      }      
    });
  }

  getFileName(path: string | undefined): string {
    if (!path) {
      return '';
    }
    return path.split('/').pop() || '';
  }
}